const input = $json || {};
const headers = input.headers || {};
const body = input.body || {};

// IMPORTANTE: reemplaza este texto por el MISMO secreto de Vercel.
const EXPECTED_SECRET = 'CAMBIA_ESTE_SECRETO_POR_UNO_DE_32_CARACTERES';
const receivedSecret = String(headers['x-eagles-secret'] || headers['X-Eagles-Secret'] || '');

if (!receivedSecret || receivedSecret !== EXPECTED_SECRET) {
  throw new Error('Solicitud no autorizada');
}

const request = body.copy_request || {};
const clean = (value) => String(value || '').trim();
const channels = Array.isArray(request.channels) && request.channels.length
  ? request.channels.map(clean).filter(Boolean)
  : ['Facebook', 'Instagram'];

if (!clean(request.product_topic)) {
  throw new Error('Falta product_topic');
}

const categoryLabels = {
  social: 'redes sociales',
  taller: 'servicios del taller de transmisiones',
  course: 'curso o capacitación de transmisiones'
};

const facts = [
  clean(request.brief),
  clean(request.call_to_action) ? `CTA solicitado: ${clean(request.call_to_action)}` : '',
  clean(request.audience) ? `Audiencia: ${clean(request.audience)}` : '',
  clean(request.image_brief) ? `Brief visual: ${clean(request.image_brief)}` : ''
].filter(Boolean).join('\n');

const normalizedTopic = clean(request.product_topic).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const normalizedObjective = clean(request.objective).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const isWorkshopConvencionales = normalizedTopic.includes('workshop') && normalizedTopic.includes('convencional');
const isWhatsAppWarmup = channels.length === 1 && channels[0].toLowerCase() === 'whatsapp'
  && normalizedObjective.includes('calentamiento');
const hasSocialChannel = channels.some((channel) => ['facebook', 'instagram', 'tiktok'].includes(channel.toLowerCase()));

const WORKSHOP_GROUP_URL = 'https://chat.whatsapp.com/Gu955o9muhZ2eJGOaRw0wS?s=cl&p=i&mlu=4&ilr=4';
const WORKSHOP_HOTMART_URL = 'https://pay.hotmart.com/U107474945W?bid=1788557927997';

let structureRules = '';
if (isWorkshopConvencionales && isWhatsAppWarmup) {
  structureRules = `\nESTRUCTURA OBLIGATORIA PARA CALENTAMIENTO EN GRUPO DE WHATSAPP:\n1. Abre con una línea cercana y energética. Puedes usar “⚙️ ¡CARNALITOS!” o una variante natural, sin repetir exactamente la misma frase siempre.\n2. Segundo párrafo: explica en 1 o 2 frases qué aprenderán o por qué este tema importa en el taller.\n3. Después coloca un bloque visual de datos, cada dato en su propia línea:\n📅 2 y 3 de octubre\n💻 Online en vivo vía Zoom\n💲 17 USD\n4. Cierra con una frase breve de urgencia o invitación, sin exagerar.\n5. Últimas dos líneas exactamente con CTA de pago:\n👉 Inscríbete aquí:\n${WORKSHOP_HOTMART_URL}\n6. NO uses el link del grupo de WhatsApp en el calentamiento interno.\n7. Mantén el copy compacto y fácil de leer en WhatsApp.`;
} else if (isWorkshopConvencionales && hasSocialChannel) {
  structureRules = `\nESTRUCTURA OBLIGATORIA PARA COPY DE REDES:\n1. Primera línea: gancho o pregunta basada en un problema real del técnico/taller. Debe generar identificación inmediata.\n2. Segundo párrafo: beneficio concreto de la Workshop en 1 o 2 frases, sin prometer resultados económicos.\n3. Cierre con invitación clara a entrar al grupo para recibir la información.\n4. Últimas dos líneas exactamente:\n🔥 Únete al grupo y recibe toda la información para asegurar tu acceso:\n👉 ${WORKSHOP_GROUP_URL}\n5. NO pongas el link de Hotmart en el copy de captación para redes.\n6. No satures con todos los datos del evento; el objetivo es llevarlos al grupo.`;
}

const systemPrompt = `Eres copywriter de Eagles Digital Solutions y Transmisiones Automáticas Eagles.

Escribe copys breves, claros, directos y listos para publicar en español de México. La audiencia principal son técnicos, transmisionistas y dueños de taller. Usa emojis con moderación y un llamado a la acción sencillo.

REGLAS OBLIGATORIAS:
- Usa únicamente los datos recibidos.
- Nunca inventes precios, fechas, horarios, lugares, promociones, garantías, enlaces ni disponibilidad.
- Si un dato no viene, omítelo sin poner espacios pendientes ni decir que falta.
- No prometas resultados económicos.
- En servicios de taller no des un diagnóstico definitivo por mensaje; invita a compartir marca, modelo, año y síntomas o a agendar diagnóstico.
- Si hay varios canales, entrega una sola versión que funcione bien en los canales solicitados, salvo que se pida explícitamente más de una variante.
- Para WhatsApp usa tono cercano; “carnalitos” puede usarse cuando sea un calentamiento para grupo.
- Mantén párrafos cortos y separaciones visuales. Los datos de fecha, modalidad y precio deben ir en líneas independientes cuando se trate de calentamientos.
- Respeta los enlaces literalmente; no los acortes, modifiques ni inventes parámetros.
- No expliques tu proceso.
- Devuelve únicamente JSON válido.${structureRules}

FORMATO:
{"copy":"texto listo para publicar","image_prompt":"prompt visual o cadena vacía"}`;

const userPrompt = `Crea un copy con estos datos:
Categoría: ${categoryLabels[request.category] || clean(request.category) || 'redes sociales'}
Tema: ${clean(request.product_topic)}
Objetivo: ${clean(request.objective) || 'Venta'}
Canales: ${channels.join(', ')}
Tono: ${clean(request.tone) || 'Directo y profesional'}
Requiere imagen: ${request.needs_image === true ? 'sí' : 'no'}
Datos confirmados:
${facts || 'No hay datos adicionales; trabaja solamente con el tema y omite detalles no confirmados.'}`;

return [{
  json: {
    request_id: clean(body.request_id),
    ollama_request: {
      model: 'qwen2.5:3b',
      stream: false,
      keep_alive: '30m',
      format: {
        type: 'object',
        properties: {
          copy: { type: 'string' },
          image_prompt: { type: 'string' }
        },
        required: ['copy', 'image_prompt']
      },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      options: {
        temperature: 0.35,
        num_predict: 650,
        num_ctx: 4096
      }
    }
  }
}];

let content = String($json?.message?.content ?? $json?.response ?? '').trim();
content = content.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

let parsed = null;
try {
  parsed = JSON.parse(content);
} catch {
  const start = content.indexOf('{');
  const end = content.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { parsed = JSON.parse(content.slice(start, end + 1)); } catch { parsed = null; }
  }
}

const copy = String(parsed?.copy || content || '').trim();
if (!copy) throw new Error('Ollama no devolvió un copy');

return [{
  json: {
    copy,
    image_prompt: String(parsed?.image_prompt || '').trim(),
    execution_id: String($execution.id)
  }
}];
